mapping.statement:
SELECT
id,
password,
nickname,
last_name,
first_name,
created_at,
updated_at,
country,
email
FROM
svc_users
WHERE
{{ if .FilterGroup }}
{{ range $counter, $filter := .FilterGroup.Filters }}
AND {{$filter.ToSQLStmt}}
{{end}}
{{ end }}
{{ if .Order }}
ORDER BY {{ .Order.By }} {{ if eq .Order.Direction "asc" }}ASC{{ else }}DESC{{end}}
{{ if .Pagination}}
LIMIT {{.Pagination.Limit}} OFFSET {{.Pagination.Offset}}
{{ end }}
{{ end }}
